function matchDetails(m){const fs=fieldDefs('match'),rs=D.records.filter(r=>r.matchId===m.id),ps=allPlayers().filter(p=>p.active!==false||rs.some(r=>r.playerId===p.id));return `<section id="match-details" class="panel stack"><div class="line between"><h2>${esc(m.opponent)} · Schede partita</h2><div class="actions">${matchFormationButton(m)}</div></div>${staff()?attendanceSummary(m):''}<p class="muted prewrap">${esc(m.notes||'Nessuna nota.')}</p><p class="muted">Inserisci le statistiche dei partecipanti. Solo le partite concluse entrano nei totali.</p>${ps.length?table(['Giocatore','Presenza',...fs.map(f=>f.name),'Note','Azioni'],ps.map(p=>{let r=rs.find(x=>x.playerId===p.id);return [esc(p.name),r?(r.appeared===false?'No':'Sì'):'—',...fs.map(f=>valueHTML(r?.values?.[f.id])),esc(r?.notes||'—'),staff()?button('Compila','record',recordId(m.id,p.id)):'—']})):empty('Nessun giocatore disponibile.')}</section>`;}
