function legacyAvailability(){const ms=plannedMatches(),m=ms.find(m=>m.id===matchId)||ms[0];if(!m)return top('Presenze','Convocazioni e disponibilità')+empty('Nessuna partita programmata.');matchId=m.id;const ps=activePlayers(),own=myPlayer();return top('Presenze','Rispondi con un tocco · aggiornamento condiviso',staff()?button('+ Nuovo impegno','edit-match','','primary'):'')+`<div class="panel">${field('Impegno',select('match',ms.map(m=>[m.id,`${fmtDate(m.date)} ${m.time||''} · ${m.opponent}`]),m.id,'id="avail-match"'))}</div>${eventCard(m)}<div class="stack">${Object.keys(STATUS).map(k=>{const group=ps.filter(p=>(response(m,p)?.status||'pending')===k);return `<section class="panel stack"><h2 class="presence-heading ${k}">${STATUS[k]} · ${group.length}</h2>${group.length?group.map(p=>{const r=response(m,p),editable=staff()||own?.id===p.id;return `<div class="attendance-row"><div><strong>${esc(p.name)}${own?.id===p.id?' (tu)':''}</strong>${r?.note?`<p class="muted prewrap">${esc(r.note)}</p>`:''}</div>${editable?`<div class="attendance-actions">${responseButtons(m,p,true)}${button('Nota / stato','set-avail',p.id,'subtle')}</div>`:''}</div>`}).join(''):'<small>Nessun giocatore</small>'}</section>`}).join('')}</div>`;}
